        const state = sdk.getState();
        const skill = state?.skills?.find(s => s.name.toLowerCase() === name.toLowerCase());
        return skill || { level: 1, baseLevel: 1, experience: 0 };
    }

    // Helper to get HP
    function getHP() {
        const state = sdk.getState();
        const hpSkill = state?.skills?.find(s => s.name === 'Hitpoints');
        if (hpSkill) {
            // Note: level is current HP, baseLevel is max HP
            return { current: hpSkill.level, max: hpSkill.baseLevel };
        }
        return { current: 10, max: 10 };
    }
